{{ config(materialized='table') }} with runs as ( select pipeline_id, pipeline_key, pipeline_name, integration_id, created_at_utc, updated_at_utc from {{ ref('stg_orchestra__pipeline_runs') }} ), ranked as ( select *, row_number() over (partition by pipeline_id order by coalesce(updated_at_utc, created_at_utc) desc) as rn from runs ) select pipeline_id, pipeline_key, pipeline_name, integration_id, coalesce(updated_at_utc, created_at_utc) as effective_at_utc from ranked where rn = 1
